from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
logger = BackgroundLogger.Instance()


def check_rat(func):

    def checking_function(*args, **kwargs):
        rat = None
        if kwargs.get('rat', 'common'):
            rat = kwargs.get('rat', 'common')
        elif kwargs.get('req_rat', 'common'):
            rat = kwargs.get('req_rat', 'common')
        if rat.lower() in get_config_variable(['rat_env']):
            return func(*args, **kwargs)
        else:
            logger.info('RAT {} ignored'.format(rat))
    return checking_function

